import{_ as r,o as e,c as o,a5 as s}from"./chunks/framework.DJo0M80U.js";const k=JSON.parse('{"title":"核心踩坑清单","description":"序号 坑点 说明 1️⃣ 依赖 node only 模块 比如：store、process、global、Buffer 等，Vite 编译时打包进 worker 后会出错。 2️⃣ 模块打包不兼容 worker 里 import 的模块如果使用了 CommonJS，容易导致 Vi。","frontmatter":{"title":"核心踩坑清单","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","进阶语言能力"],"description":"序号 坑点 说明 1️⃣ 依赖 node only 模块 比如：store、process、global、Buffer 等，Vite 编译时打包进 worker 后会出错。 2️⃣ 模块打包不兼容 worker 里 import 的模块如果使用了 CommonJS，容易导致 Vi。","sidebarWeight":45,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/webworkers/核心踩坑清单/核心踩坑清单.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/07-进阶语言能力/核心踩坑清单/核心踩坑清单.md","filePath":"posts/JavaScript系统教程/07-进阶语言能力/核心踩坑清单/核心踩坑清单.md"}'),n={name:"posts/JavaScript系统教程/07-进阶语言能力/核心踩坑清单/核心踩坑清单.md"};function a(d,t,i,p,g,l){return e(),o("div",null,[...t[0]||(t[0]=[s('<div><h1 id="核心踩坑清单" tabindex="-1">核心踩坑清单 <a class="header-anchor" href="#核心踩坑清单" aria-label="Permalink to &quot;核心踩坑清单&quot;">​</a></h1><blockquote><p>本节目标：理解“核心踩坑清单”的核心思路，并能把它用于实际开发或面试表达。 | | | | |---|---|---| |<strong>序号</strong>|<strong>坑点</strong>|<strong>说明</strong>| |1️⃣|<strong>依赖 node-only 模块</strong>|比如：store、process、global、Buffer 等，Vite 编译时打包进 worker 后会出错。| |2️⃣|<strong>模块打包不兼容</strong>|worker 里 import 的模块如果使用了 CommonJS，容易导致 Vite 打包失败或语法错误。| |3️⃣|<strong>路径问题</strong>|worker 文件路径需要 Vite 正确处理，推荐用 new URL(&#39;./worker.ts&#39;, import.meta.url)。| |4️⃣|<strong>静态 import 陷阱</strong>|worker 里用普通的 import 可能导致整个依赖链被过度打包，建议使用动态 import（import()）| |5️⃣|<strong>无法共享主线程上下文</strong>|worker 里没有 window、document、localStorage、Vue 组件实例、Pinia、Vuex。只能通过 postMessage 传递数据。| |6️⃣|<strong>TypeScript 类型支持不完善</strong>|Worker 全局对象（self）和事件类型容易写错，推荐手动声明类型，或者使用 vite-plugin-web-worker 辅助。| |7️⃣|<strong>跨域引用问题</strong>|有些情况下 worker 文件被当作模块请求，服务端没配置好 CORS 导致无法加载。尤其是在生产部署时。| |8️⃣|<strong>大数据通信阻塞 UI</strong>|传输大对象时容易卡死 UI，推荐使用 structuredClone() 或 Transferable Objects。| |9️⃣|<strong>Vite 构建模式不同</strong>|开发模式和生产打包路径、URL、import 语法有差异。| |🔟|<strong>不能访问全局 polyfill</strong>|比如：window.fetch() 是可用的，但如果用了某些库提供的 polyfill，在 worker 里未必能复用。| |1️⃣1️⃣|<strong>worker 关闭和内存泄漏</strong>|创建了大量 worker 没有主动关闭 (worker.terminate()) 容易内存泄漏。| |1️⃣2️⃣|<strong>Source Map 调试不友好</strong>|Vite 打包后的 worker 脚本调试不如主线程直观，尤其是在异常栈追踪时。|</p></blockquote><p><strong>✅</strong> <strong>额外的框架相关坑（你目前这种 Vite + Vue 项目）</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>序号</strong></td><td><strong>坑点</strong></td><td><strong>说明</strong></td></tr><tr><td>1️⃣</td><td>Vue Composition API 不可用</td><td>worker 里无法用 ref(), reactive(), computed() 等。</td></tr><tr><td>2️⃣</td><td>Pinia / Vuex 状态管理不可用</td><td>worker 是线程隔离，不能共享任何状态管理库。</td></tr><tr><td>3️⃣</td><td>import alias 需要 vite.config.ts 配置好 resolve.alias</td><td>否则 worker 里用 @/utils 这种路径会编译失败。</td></tr><tr><td>4️⃣</td><td>Vite 没内置 worker loader</td><td>需要手动用 new Worker(new URL(&#39;./worker.ts&#39;, import.meta.url), { type: &#39;module&#39; })。</td></tr></tbody></table><p><strong>✅</strong> <strong>稳定最佳实践模板</strong> 我给你总结一份【以后你可以直接套用的 Vite + Vue + TypeScript 下的 Web Worker 模板】：</p><p>ts 复制编辑 // main.ts 里创建 workerconst worker = new Worker(new URL(&#39;@/workers/myWorker.ts&#39;, import.meta.url), { type: &#39;module&#39; }) worker.postMessage({ type: &#39;processOrders&#39;, data: myData }) worker.onmessage = (event) =&gt; { console.log(&#39;收到worker消息&#39;, event.data)}</p><p>ts 复制编辑 // workers/myWorker.tsself.addEventListener(&#39;message&#39;, async (event: MessageEvent&lt;MyWorkerMessage&gt;) =&gt; { const { type, data } = event.data if (type === &#39;processOrders&#39;) { // 动态导入，避免静态依赖打包问题 const { heavyCompute } = await import(&#39;@/utils/heavyCompute&#39;) const result = heavyCompute(data) self.postMessage({ type: &#39;processedOrders&#39;, data: result }) }})</p><p>ts 复制编辑 // vite.config.ts (建议 alias 配置好)resolve: { alias: { &#39;@&#39;: path.resolve(__dirname, &#39;./src&#39;) }} ✅ 这套写法能最大程度避免绝大多数坑。</p><p><strong>✅</strong> <strong>工具推荐</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>工具</strong></td><td><strong>用途</strong></td></tr><tr><td>vite-plugin-web-worker</td><td>自动帮你处理 worker 路径、打包、类型声明</td></tr><tr><td>vite-plugin-worker-loader</td><td>兼容 webpack-style worker 引用</td></tr></tbody></table><p><strong>✅</strong> <strong>最后一条建议</strong><strong>Worker 本质上就是 &quot;沙箱&quot;。</strong> 里面逻辑保持纯净、纯数据处理，效果会非常稳定。 你可以把 Worker 当成一个前端的 &quot;后端服务&quot; 去设计，越纯越好。</p><p>👉 <strong>要不要我顺手帮你做一个适合你项目的：</strong></p><ul><li>✅ Web Worker 最佳实践模板</li><li>✅ 兼容你现在 Vite + Vue + TS 环境</li><li>✅ 不会踩坑，可复用</li></ul><p>—— 你只要说一声 &quot;要&quot;，我马上帮你整理好。</p></div>',1)])])}const m=r(n,[["render",a]]);export{k as __pageData,m as default};
